/**
 * From detector output to an explained, actionable finding.  Rule-based and auditable: every
 * finding names the rule that produced it (shared/rules.json) and the countermeasure sources
 * (shared/countermeasures.json).  No text here is generated by a language model.
 */
import rulesJson from '../../../shared/rules.json'
import cmJson from '../../../shared/countermeasures.json'
import refsJson from '../../../shared/references.json'
import { concernDev, deployedScore, episodes, inverseTransform, type ModelJson } from './detect'
import { IND, phaseAt, rawSeries, SYM, symptomsOn } from './mission'
import type { Change, CrewAnalysis, Entry, Factor, Finding, Mission, OpenItem, Reading, Status, Tier, Urgency } from './types'

export interface Countermeasure { id: string; title: string; type: string; refs: string[]; text: string }
export const COUNTERMEASURES = cmJson as Countermeasure[]
export const CM: Record<string, Countermeasure> = Object.fromEntries(COUNTERMEASURES.map((c) => [c.id, c]))
export const REFS = refsJson as Record<string, { text: string; url: string | null }>

type Cond =
  | { u: string; min: number }
  | { u: string; max: number }
  | { sym: string; min: number }
  | { env: string; min: number }
  | { phase_days_max: number }
  | { phase_days_min: number }
  | { alert_days_min: number }
  | { pattern_days_min: number }
  | { always: boolean }
  | { red_flag: boolean }
  | { val: string; min?: number; max?: number; count?: number }
  | { run: string; min?: number; max?: number; days: number }
  | { rel: string; max: number }
  | { all: Cond[] }
  | { any: Cond[] }

export interface Rule {
  id: string
  scope: 'personal' | 'environment' | 'symptom' | 'adaptation' | 'vital'
  urgency: Urgency
  priority: number
  title: string
  when: Cond
  summary: string
  action: string
  steps: string[]
  tier: Tier
  tier_reason: string
  cm: string[]
  categories: string[]
  escalate?: { when: Cond; tier: Tier; reason: string }[]
}
export const RULES = (rulesJson.rules as unknown as Rule[]).slice().sort((a, b) => a.priority - b.priority)
export const RULE: Record<string, Rule> = Object.fromEntries(RULES.map((r) => [r.id, r]))

export interface RuleFeatures {
  u: Record<string, number>
  sym: Record<string, number>
  env: Record<string, number>
  phaseDays: number
  hasPhase: boolean
  /** days the detector's alert has been open */
  alertDays: number
  /** days in a row the same pattern rule has applied (escalation counts these, not the whole alert) */
  patternDays: number
  /** readings in force for fixed-threshold rules: every reading from the most recent day that has one (within a week).
   *  A rule fires if ANY of them meets it, so a later normal reading the same day does not erase an abnormal one. */
  val: Record<string, number[]>
  /** the last n measured values of an indicator (within n + 3 days), newest last; empty if fewer than n */
  run: (ind: string, n: number) => number[]
  /** relative change against the pre-flight level */
  rel: Record<string, number>
  redFlag: boolean
}

export function evalCond(c: Cond, f: RuleFeatures): boolean {
  if ('all' in c) return c.all.every((x) => evalCond(x, f))
  if ('any' in c) return c.any.some((x) => evalCond(x, f))
  if ('u' in c && 'max' in c) return !((f.u[c.u] ?? -Infinity) > c.max)
  if ('u' in c) return (f.u[c.u] ?? -Infinity) >= c.min
  if ('sym' in c) return (f.sym[c.sym] ?? 0) >= c.min
  if ('env' in c) return (f.env[c.env] ?? -Infinity) >= c.min
  if ('phase_days_max' in c) return f.hasPhase && f.phaseDays <= c.phase_days_max
  if ('phase_days_min' in c) return f.hasPhase && f.phaseDays >= c.phase_days_min
  if ('alert_days_min' in c) return f.alertDays >= c.alert_days_min
  if ('pattern_days_min' in c) return f.patternDays >= c.pattern_days_min
  if ('always' in c) return true
  if ('red_flag' in c) return f.redFlag
  if ('val' in c) {
    const vs = (f.val[c.val] ?? []).filter((v) => !Number.isNaN(v))
    return vs.filter((v) => (c.min === undefined || v >= c.min) && (c.max === undefined || v <= c.max)).length >= (c.count ?? 1)
  }
  if ('run' in c) {
    const v = f.run(c.run, c.days)
    return v.length >= c.days && v.every((x) => (c.min === undefined || x >= c.min) && (c.max === undefined || x <= c.max))
  }
  if ('rel' in c) return (f.rel[c.rel] ?? 0) <= c.max
  return false
}

/** Indicators a rule's condition refers to (they are shown first as the evidence for that rule). */
/** Entered readings a fixed rule's condition refers to. */
export function condVals(c: Cond): string[] {
  if ('all' in c) return c.all.flatMap(condVals)
  if ('any' in c) return c.any.flatMap(condVals)
  if ('val' in c) return [c.val.replace(/_manual$|_rise$/, '')]
  return []
}

/** Every indicator a condition refers to, whichever way (deviation, entered value, run of values, relative change). */
export function condAll(c: Cond): string[] {
  if ('all' in c) return c.all.flatMap(condAll)
  if ('any' in c) return c.any.flatMap(condAll)
  if ('u' in c) return [c.u]
  if ('val' in c) return [c.val.replace(/_manual$|_rise$/, '')]
  if ('run' in c) return [c.run]
  if ('rel' in c) return [c.rel]
  return []
}

/** Indicators a condition refers to through entered values, runs or relative change (not deviations). */
export function condFixed(c: Cond): string[] {
  if ('all' in c) return c.all.flatMap(condFixed)
  if ('any' in c) return c.any.flatMap(condFixed)
  if ('val' in c) return [c.val.replace(/_manual$|_rise$/, '')]
  if ('run' in c) return [c.run]
  if ('rel' in c) return [c.rel]
  return []
}

export function condIndicators(c: Cond): string[] {
  if ('all' in c) return c.all.flatMap(condIndicators)
  if ('any' in c) return c.any.flatMap(condIndicators)
  if ('u' in c && 'min' in c) return [c.u]
  return []
}

const TIER_RANK: Record<Tier, number> = { self: 0, cmo: 1, ground: 2 }

export function applyRule(r: Rule, f: RuleFeatures): { tier: Tier; reason: string } {
  let tier = r.tier
  let reason = r.tier_reason
  for (const e of r.escalate ?? []) {
    if (TIER_RANK[e.tier] > TIER_RANK[tier] && evalCond(e.when, f)) {
      tier = e.tier
      reason = e.reason
    }
  }
  return { tier, reason }
}

/** a single night shorter than this turns the sleep area amber (also used by the Today routine line) */
export const SLEEP_FLOOR_H = 5

const URGENCY_STATUS: Record<Urgency, Status> = { now: 'urgent', today: 'act', routine: 'watch' }
const mean = (v: number[]) => (v.length ? v.reduce((a, b) => a + b, 0) / v.length : NaN)
const lastValid = (v: number[], day: number, back = 3) => {
  for (let t = day; t > day - back && t >= 0; t--) if (!Number.isNaN(v[t])) return v[t]
  return NaN
}

export interface DayAnalysis {
  status: Status
  findings: Finding[]
  /** indicators that moved, most unusual first (shown even when no alert is open) */
  changes: Change[]
  learning: boolean
  baselineDays: number
  adapting: { name: string; day: number } | null
  /** days in a row, up to today, with no reading at all (2 or more means the status cannot be trusted) */
  staleDays: number
  u3: Record<string, number>
  systems: Record<string, Status>
  /** the same statuses grouped by sharing area */
  categories: Record<string, Status>
  /** cabin CO2 (mmHg) when it is above the level linked to headaches but below the alert rule */
  co2Advisory: number | null
  /** exercise is on hold because an open finding says to stop or rest */
  exerciseHold: boolean
  /** 'now' and 'today' findings from the crew member's own entries in the last 30 days (closing them is the medical officer's job) */
  openItems: OpenItem[]
  alert: { start: number; days: number; tier: 'notice' | 'alert'; score: number } | null
  features: RuleFeatures
}

export const URGENCY_LABEL: Record<Urgency, string> = { now: 'Now', today: 'Today', routine: 'At the next routine opportunity' }
export const WHO_LABEL: Record<Tier, string> = {
  self: 'You manage this yourself',
  cmo: 'The crew medical officer',
  ground: 'The medical officer, who consults the flight surgeon when a link is available',
}

export const TIER_LABEL: Record<Tier, string> = {
  self: 'Manage it yourself',
  cmo: 'Inform the crew medical officer',
  ground: 'Medical officer leads on board; flight surgeon consulted when a link is available',
}

export const STATUS_LABEL: Record<Status, string> = {
  learning: 'Learning your normal',
  steady: 'Steady',
  watch: 'Worth a look',
  act: 'Act today',
  urgent: 'Act now',
}

/** Rules whose advice includes stopping or holding exercise.  While one is open, "do today's session"
 *  is never shown and the routine shows exercise on hold. */
export const NO_EXERCISE = new Set(['R-RED', 'R-V-HR1R', 'R-V-SPO2', 'R-V-TEMP-HI', 'R-V-TEMP', 'R-V-HR0', 'R-V-HR2', 'R-V-HR1', 'R-V-HR', 'R-V-BP-LO2', 'R-V-BP-LO', 'R-V-BP-HI2', 'R-V-GLU-LO2', 'R-V-GLU-LO', 'R-SYM-ILL', 'R-ILL', 'R-CO2-HI', 'R-SPE-V', 'R-SPO2'])
/** spot readings typed at check-in are kept apart from the wearable's overnight series, so a fingertip
 *  check never overwrites the overnight value that prompted it */
export const SPOT_KEY: Record<string, string> = { rhr: 'rhr_spot', spo2: 'spo2_spot' }

/** Closure notes by item key, with the time each was written (from the action log). */
export type Closures = Map<string, number>
export function closuresFrom(actions: { did: string; alertKey: string; ts: number }[]): Closures {
  const c: Closures = new Map()
  for (const a of actions) if (a.did.startsWith('Closed')) c.set(a.alertKey, Math.max(c.get(a.alertKey) ?? 0, a.ts))
  return c
}
/** An item is closed only by a note written after the latest reading or check-in behind it:
 *  a new abnormal reading after the note reopens it. */
export const isClosed = (closed: Closures, key: string, ts: number) => (closed.get(key) ?? -Infinity) >= ts

export function analyzeDay(
  m: Mission, crewId: string, an: CrewAnalysis, model: ModelJson, day: number, entries: Entry[], closed: Closures = new Map(),
): DayAnalysis {
  const ids = model.indicators
  const p = model.params
  const sc = an.scored
  const d = ids.length
  const uAt = (t: number, j: number) => concernDev(sc.z[t]?.[j] ?? NaN, model.concern[j])

  // --- three-day deviation per indicator -------------------------------------------------
  const u3: Record<string, number> = {}
  for (let j = 0; j < d; j++) {
    const v: number[] = []
    for (let t = Math.max(0, day - 2); t <= day; t++) if (!Number.isNaN(uAt(t, j))) v.push(uAt(t, j))
    u3[ids[j]] = mean(v)
  }
  const baselineDays = sc.z.slice(0, day + 1).filter((r) => r.some((v) => !Number.isNaN(v))).length
  const learning = baselineDays < 3

  // --- what changed ------------------------------------------------------------------------
  const changes: Change[] = []
  for (let j = 0; j < d; j++) {
    const id = ids[j]
    const uu = u3[id]
    const uToday = uAt(day, j)
    if (!(uu >= 0.8) && !(uToday >= 2)) continue
    const raw = rawSeries(m, crewId, id, entries)
    const tLast = [day, day - 1, day - 2].find((t) => t >= 0 && !Number.isNaN(sc.z[t][j]))
    if (tLast === undefined) continue
    const mt = sc.m[tLast][j]
    const st = sc.s[tLast][j]
    const tr = model.transform[j]
    let daysOut = 0
    for (let t = day; t >= 0; t--) {
      const q = uAt(t, j)
      if (Number.isNaN(q)) continue
      if (q >= 1.2) daysOut++
      else break
    }
    const notable = uu >= 1.2 || uToday >= 2
    const hist: number[] = []
    for (let t = Math.max(0, day - 60); t < day - 2; t++) if (!Number.isNaN(uAt(t, j))) hist.push(uAt(t, j))
    const pct = hist.length >= 10 ? hist.filter((h) => h < uu).length / hist.length : NaN
    changes.push({
      ind: id, value: raw[tLast], expected: inverseTransform(mt, tr),
      lo: inverseTransform(mt - 2 * st, tr), hi: inverseTransform(mt + 2 * st, tr),
      u3: uu, z: sc.z[tLast][j], direction: sc.z[tLast][j] >= 0 ? 'higher' : 'lower', percentile: pct, daysOut,
      nHist: hist.length, nLess: hist.filter((h) => h < uu).length, uToday: Number.isNaN(uToday) ? uu : uToday, notable,
    })
  }
  changes.sort((a, b) => Math.max(b.u3, b.uToday ?? 0) - Math.max(a.u3, a.uToday ?? 0))

  // --- symptoms, environment, phase --------------------------------------------------------
  const sym: Record<string, number> = {}
  for (let t = Math.max(0, day - 2); t <= day; t++) for (const s of symptomsOn(m, crewId, t, entries)) sym[s] = (sym[s] ?? 0) + 1
  const co2 = rawSeries(m, crewId, 'co2', entries)
  const rad = rawSeries(m, crewId, 'rad', entries)
  const co23 = mean(co2.slice(Math.max(0, day - 2), day + 1).filter((v) => !Number.isNaN(v)))
  const radHist = rad.slice(Math.max(m.pre_days, day - 30), Math.max(0, day - 1)).filter((v) => !Number.isNaN(v)).sort((a, b) => a - b)
  const radMed = radHist.length >= 5 ? radHist[Math.floor(radHist.length / 2)] : NaN
  const rad3 = Math.max(...[day, day - 1, day - 2].map((t) => (t >= 0 && !Number.isNaN(rad[t]) ? rad[t] : -Infinity)))
  const env: Record<string, number> = { co2_3d: co23, co2: lastValid(co2, day), rad: lastValid(rad, day), rad_ratio: lastValid(rad, day) / radMed, rad_ratio_3d: rad3 / radMed, rad_sum_3d: [day, day - 1, day - 2].reduce((acc, t) => acc + (t >= 0 && !Number.isNaN(rad[t]) ? rad[t] : 0), 0) }
  const ph = phaseAt(m, day)
  const hasPhase = m.phases.some((q) => day >= q.start)
  const adapting = hasPhase && ph.since < 14 ? { name: ph.name, day: ph.since + 1 } : null

  // --- detector state ----------------------------------------------------------------------
  const eps = episodes(deployedScore(sc, model), model.thresholds.notice, p.merge_gap, day)
  const last = eps[eps.length - 1]
  let alert: DayAnalysis['alert'] = null
  if (last && day - last[1] <= p.merge_gap) {
    let peak = 0
    for (let t = last[0]; t <= day; t++) if (deployedScore(sc, model)[t] > peak) peak = deployedScore(sc, model)[t]
    alert = { start: last[0], days: day - last[0] + 1, tier: peak >= model.thresholds.alert ? 'alert' : 'notice', score: peak }
  }
  const mineE = entries.filter((e) => e.crew === crewId && e.mission === m.id)
  // readings in force: every reading of the most recent day that has one, newest day first.  Entries
  // keep an append-only log, so a repeat reading never erases the first one.
  const inForce = (id: string, manualOnly = false, back = 7): { day: number; vals: number[]; log: Reading[] } => {
    const series = manualOnly ? null : rawSeries(m, crewId, id, [])
    for (let t = day; t > day - back && t >= 0; t--) {
      const e = mineE.find((q) => q.day === t)
      const all = (e?.readings ?? []).filter((r) => r.ind === id)
      const log = all.filter((r) => !r.void)
      if (log.length) return { day: t, vals: log.map((r) => r.v), log: all }
      if (all.length) continue   // every reading that day was withdrawn
      if (e && id in e.values) return { day: t, vals: [e.values[id]], log: [{ ind: id, v: e.values[id], ts: e.ts }] }
      if (series && !Number.isNaN(series[t])) return { day: t, vals: [series[t]], log: [] }
    }
    return { day, vals: [], log: [] }
  }
  const run = (id: string, n: number): number[] => {
    const v = rawSeries(m, crewId, id, entries)
    const out: number[] = []
    for (let t = day; t > day - n - 3 && t >= 0 && out.length < n; t--) if (!Number.isNaN(v[t])) out.unshift(v[t])
    return out.length >= n ? out : []
  }
  const massS = rawSeries(m, crewId, 'mass', entries)
  const pre = massS.slice(0, Math.max(1, m.pre_days)).filter((v) => !Number.isNaN(v)).sort((x, y) => x - y)
  const massNow = lastValid(massS, day, 10)
  const rel: Record<string, number> = m.pre_days > 0 && pre.length >= 2 && !Number.isNaN(massNow) && day >= m.pre_days ? { mass: massNow / pre[Math.floor(pre.length / 2)] - 1 } : {}
  // a red flag stays open for three days unless a later check-in by the crew member leaves it out;
  // after that it remains on the open-items list until the medical officer closes it
  const lastEntry = mineE.filter((q) => q.day <= day && q.day > day - 3).sort((a, b) => b.day - a.day)[0]
  // a red flag ticked in the last three days stays until the medical officer closes it, even if a later
  // check-in leaves it out
  const recentFlags = mineE.filter((q) => q.day <= day && q.day > day - 3 && !isClosed(closed, `open|${m.id}|${crewId}|R-RED|${q.day}`, q.ts)).flatMap((q) => [...q.symptoms, ...(q.redFlags ?? [])])
  const redSyms = [...new Set([...symptomsOn(m, crewId, day, entries), ...(lastEntry?.symptoms ?? []), ...recentFlags].filter((x) => SYM[x]?.red_flag))]
  const redFlag = redSyms.length > 0
  const patientIsCmo = m.crew.find((c) => c.id === crewId)?.role === 'cmo'
  const tOral = rawSeries(m, crewId, 'temp_oral', entries)
  const tPrev = tOral.slice(0, Math.max(0, day - 6)).filter((v) => !Number.isNaN(v)).sort((x, y) => x - y)
  const tUsual = tPrev.length >= 3 ? tPrev[Math.floor(tPrev.length / 2)] : NaN
  const force: Record<string, ReturnType<typeof inForce>> = {
    temp_oral: inForce('temp_oral'), glucose: inForce('glucose'), sbp: inForce('sbp'), dbp: inForce('dbp'), spo2: inForce('spo2_spot', true), rhr: inForce('rhr_spot', true),
  }
  const val: Record<string, number[]> = {
    temp_oral: force.temp_oral.vals, temp_oral_rise: force.temp_oral.vals.map((v) => v - tUsual), glucose: force.glucose.vals, sbp: force.sbp.vals, dbp: force.dbp.vals,
    spo2_manual: force.spo2.vals, rhr_manual: force.rhr.vals,
  }
  const f: RuleFeatures = { u: u3, sym, env, phaseDays: ph.since, hasPhase, alertDays: alert?.days ?? 0, patternDays: 0, val, run, rel, redFlag }
  // the same features as they stood on an earlier day (deviations and symptoms; entered readings and cabin stay as today)
  const featAt = (t: number): RuleFeatures => {
    const u: Record<string, number> = {}
    for (let j = 0; j < d; j++) {
      const v: number[] = []
      for (let q = Math.max(0, t - 2); q <= t; q++) if (!Number.isNaN(uAt(q, j))) v.push(uAt(q, j))
      u[ids[j]] = mean(v)
    }
    const sy: Record<string, number> = {}
    for (let q = Math.max(0, t - 2); q <= t; q++) for (const x of symptomsOn(m, crewId, q, entries)) sy[x] = (sy[x] ?? 0) + 1
    return { ...f, u, sym: sy, alertDays: alert ? t - alert.start + 1 : 0, patternDays: 0 }
  }
  // How an open notice has been read, day by day.  A reading is kept while its rule still holds, unless a
  // rule higher in the table (more specific or more serious) now applies: the headline does not flip
  // back and forth between equally plausible readings.
  const ruleSeq = (skipExToday: boolean): string[] => {
    if (!alert) return []
    const out: string[] = []
    let prev: Rule | null = null
    for (let t = Math.max(alert.start, day - 59); t <= day; t++) {
      const ft = t === day ? f : featAt(t)
      const skip = (q: Rule) => t === day && skipExToday && q.id === 'R-EX'
      let cur: Rule = RULES.find((q) => q.scope === 'personal' && !skip(q) && evalCond(q.when, ft)) ?? RULE['R-GEN']
      if (prev && prev.id !== cur.id && cur.priority > prev.priority && !skip(prev) && evalCond(prev.when, ft)) cur = prev
      out.push(cur.id)
      prev = cur
    }
    return out
  }
  // days in a row with no fresh reading at all (rolling averages do not count as fresh)
  const fresh = ['rhr', 'hrv', 'spo2', 'temp', 'sleep_h', 'mood', 'pvt_rt', 'fluid', 'energy', 'ex_min', 'steps'].map((id) => rawSeries(m, crewId, id, entries))
  let staleDays = 0
  for (let t = day; t >= 0; t--) {
    if (fresh.some((v) => !Number.isNaN(v[t])) || mineE.some((q) => q.day === t)) break
    staleDays++
  }

  // --- contributing factors from the person's own recent data ---------------------------
  const factors: Factor[] = []
  const val3 = (id: string) => mean(rawSeries(m, crewId, id, entries).slice(Math.max(0, day - 2), day + 1).filter((v) => !Number.isNaN(v)))
  const exp = (id: string) => {
    const j = ids.indexOf(id)
    return j < 0 ? NaN : inverseTransform(sc.m[day]?.[j] ?? NaN, model.transform[j])
  }
  const f1 = (v: number, dgt = 1) => (Number.isNaN(v) ? '–' : v.toFixed(dgt))
  if (u3.sleep_h >= 1) factors.push({ id: 'sleep', text: 'Short sleep', evidence: `Sleep averaged ${f1(val3('sleep_h'))} h over the last three nights; your normal is ${f1(exp('sleep_h'))} h.` })
  if (u3.sleep_mid >= 1.5) factors.push({ id: 'timing', text: 'Sleep timing moved', evidence: `Your sleep period has shifted about ${f1(Math.abs(val3('sleep_mid') - exp('sleep_mid')))} h from where it usually sits.` })
  if (u3.fluid >= 1) factors.push({ id: 'fluid', text: 'Low fluid intake', evidence: `You logged ${f1(val3('fluid'))} L a day over the last three days; your normal is ${f1(exp('fluid'))} L.` })
  if (u3.ex7 >= 1) factors.push({ id: 'exercise', text: 'Less exercise than usual', evidence: `Seven-day average ${f1(lastValid(rawSeries(m, crewId, 'ex7', entries), day), 0)} min a day against your usual ${f1(exp('ex7'), 0)}.` })
  {
    const ex = rawSeries(m, crewId, 'ex_min', entries)
    const y = ex[day - 1]
    const usual = exp('ex7')
    if (!Number.isNaN(y) && !Number.isNaN(usual) && y > usual * 1.4 + 20) factors.push({ id: 'load', text: 'Hard session yesterday', evidence: `Yesterday's exercise was ${f1(y, 0)} min, well above your usual ${f1(usual, 0)}. Heart rate often runs higher the night after.` })
  }
  if (u3.energy >= 1) factors.push({ id: 'food', text: 'Eating less than planned', evidence: `About ${f1(val3('energy'), 0)}% of plan over the last three days; your normal is ${f1(exp('energy'), 0)}%.` })
  if (u3.mood >= 1) factors.push({ id: 'mood', text: 'Lower mood', evidence: `Mood check-ins averaged ${f1(val3('mood'))} of 5; your normal is ${f1(exp('mood'))}.` })
  if (co23 >= 2.5) factors.push({ id: 'co2', text: 'Cabin carbon dioxide', evidence: `Cabin CO2 averaged ${f1(co23)} mmHg over three days. Headaches become more likely the higher it goes.` })
  const symList = Object.keys(sym).filter((s) => s in SYM)
  if (symList.length) factors.push({ id: 'symptoms', text: 'Symptoms you reported', evidence: symList.map((s) => `${SYM[s].label.toLowerCase()} (${sym[s]} of the last 3 days)`).join(', ') + '.' })
  const meds = [...new Set(mineE.filter((q) => q.day <= day && q.day > day - 3).flatMap((q) => q.meds ?? []))]
  if (meds.length) factors.push({ id: 'meds', text: 'Medication you logged', evidence: `${meds.join(', ')} in the last three days. Sleep aids, decongestants, anti-nausea and pain medicines can each move heart rate, reaction time or sleep.` })
  if (adapting) factors.push({ id: 'phase', text: 'Recent gravity change', evidence: `Day ${adapting.day} of ${adapting.name.toLowerCase()}. Keel expects readings to move during adaptation and has widened your ranges.` })

  // --- rules ---------------------------------------------------------------------------------
  const findings: Finding[] = []
  const mk = (r: (typeof RULES)[number], kind: Finding['kind'], start: number, status: Status, ch: Change[], extra: Partial<Finding> = {}): Finding => {
    const t = applyRule(r, f)
    const crewWide = kind === 'environment' && r.id !== 'R-CO2H'
    const out: Finding = {
      key: `${m.id}|${crewWide ? 'crew' : crewId}|${kind === 'personal' ? 'P' : r.id}|${start}`, kind, crewWide, status, start,
      days: day - start + 1, ruleId: r.id, title: r.title, summary: r.summary, changes: ch, factors: kind === 'personal' ? factors : factors.filter((x) => ['co2', 'symptoms', 'phase', 'meds'].includes(x.id)),
      action: r.action, steps: r.steps, tier: t.tier, tierReason: t.reason, urgency: r.urgency ?? 'routine', countermeasures: r.cm, categories: r.categories,
      ...(crewWide ? { who: 'The commander and the whole crew' } : {}), ...(patientIsCmo ? { patientIsCmo: true } : {}), ...extra,
    }
    out.inds = [...new Set([...condFixed(r.when), ...out.changes.map((c) => c.ind)])]
    // a fixed rule names the reading itself: "you entered 170", not only the rule
    if (kind === 'vital' && out.readings?.length) {
      const live = out.readings.filter((q) => !q.void)
      const worst = live.length ? live.reduce((a, b) => (Math.abs(b.v - live[0].v) > Math.abs(a.v - live[0].v) ? b : a), live[0]) : undefined
      if (worst) out.title = `${r.title} (entered: ${live.length > 1 ? live.map((q) => q.v).join(', then ') : worst.v})`
    }
    // drop a step whose conditions the person's own reports already rule out
    const ruledOut = (sym.fatigue ?? 0) > 0 || (sym.cough ?? 0) > 0 || (val.temp_oral ?? []).some((v) => v >= 38)
    if (ruledOut) out.steps = out.steps.filter((x) => !/light session is reasonable/.test(x))
    // the medical officer cannot be told to see the medical officer: their backup is the commander
    return patientIsCmo && !crewWide ? forCmoAsPatient(out) : out
  }
  const firstDay = (test: (t: number) => boolean) => {
    let s = day
    while (s > 0 && test(s - 1)) s--
    return s
  }
  const rank: Record<Status, number> = { urgent: 4, act: 3, watch: 2, steady: 1, learning: 0 }
  // a symptom-led finding dates from the first day in a row on which its rule held (a red flag: from the day it was ticked)
  const symStart = (r: Rule): number => {
    if (r.id === 'R-RED') return lastEntry && lastEntry.symptoms.some((x) => SYM[x]?.red_flag) ? lastEntry.day : day
    let s0 = day
    while (s0 > 0 && s0 > day - 14 && evalCond(r.when, featAt(s0 - 1))) s0--
    return s0
  }
  for (const r of RULES) {
    if ((r.scope === 'symptom' || r.scope === 'vital') && evalCond(r.when, f)) {
      const named = condIndicators(r.when)
      // a fixed rule dates from the day of the reading it is looking at, and carries those readings
      const vals = [...new Set(condVals(r.when))].filter((v) => force[v]?.vals.length)
      const start = vals.length ? Math.min(...vals.map((v) => force[v].day)) : r.scope === 'symptom' ? symStart(r) : day
      const log = vals.flatMap((v) => force[v].log)
      // the medical officer closed it: it leaves Today (the reading stays in the log)
      const latestTs = log.length ? Math.max(...log.filter((q) => !q.void).map((q) => q.ts), 0) : mineE.find((q) => q.day === start)?.ts ?? 0
      if (r.urgency !== 'routine' && isClosed(closed, `open|${m.id}|${crewId}|${r.id}|${start}`, latestTs)) continue
      // an "act now" reading from an earlier day is no longer "now": it waits for the medical officer
      const stale = r.urgency === 'now' && start < day
      // a later reading the same day is back on the safe side of this rule: say so, but keep it for the medical officer
      const lastLive = vals.map((v) => { const live = force[v].log.filter((q) => !q.void); return live.length ? live[live.length - 1] : undefined }).filter((q): q is Reading => !!q)
      // The latest reading the same day is "back on the safe side" only if it triggers NO fixed rule on that
      // measurement (50 then 60 is still low), and, for blood sugar, only if it was taken at least 15 minutes
      // after the first abnormal one (time for the sugar to work).
      const latestF: RuleFeatures = { ...f, val: Object.fromEntries(Object.entries(f.val).map(([k, vs]) => {
        const base = k.replace(/_manual$|_rise$/, '')
        const ll = lastLive.find((q) => (SPOT_KEY[base] ?? base) === q.ind)
        return [k, ll ? (k.endsWith('_rise') ? [ll.v - tUsual] : [ll.v]) : vs]
      })) }
      const mine = condFixed(r.when)
      const anyRuleOnLatest = RULES.some((q) => q.scope === 'vital' && condFixed(q.when).some((x) => mine.includes(x)) && evalCond(q.when, latestF))
      const firstBad = log.filter((q) => !q.void)[0]
      const waited = !mine.includes('glucose') || (firstBad && lastLive.length > 0 && lastLive[lastLive.length - 1].ts - firstBad.ts >= 15 * 60 * 1000)
      const repeatOk = r.scope === 'vital' && r.urgency !== 'routine' && lastLive.length > 0 && log.filter((q) => !q.void).length > 1 && !anyRuleOnLatest && !!waited
      // a repeat already back on the safe side, but taken too soon to count (blood sugar: under 15 minutes)
      const tooSoon = !repeatOk && !anyRuleOnLatest && log.filter((q) => !q.void).length > 1 && !waited
      findings.push(mk(r, r.scope, start, repeatOk ? 'act' : URGENCY_STATUS[r.urgency ?? 'routine'], changes.filter((c) => named.includes(c.ind)).slice(0, 4), {
        ...(tooSoon ? { action: `${r.action} Your repeat (${lastLive[lastLive.length - 1].v}) came too soon to count: sugar takes about 15 minutes to work, so check again 15 minutes after the first reading.` } : {}),
        ...(log.length ? { readings: log } : {}),
        ...(repeatOk ? { urgency: 'now' as Urgency, action: `Your repeat reading (${lastLive[lastLive.length - 1].v}) is back on the safe side, so no more sugar is needed: eat a snack or your next meal now. The first reading needed the medical officer at once: if you have not told them yet, tell them now.`, tierReason: 'The first reading stays on the medical officer\'s list until they close it with a note.' } : {}),
        ...(stale ? { action: `This reading from ${m.day_label ? `${m.day_label} ${start + 1}` : `Day ${start + 1}`} is still open. If you have not yet told the medical officer, tell them now.`, tierReason: 'It stays open until the medical officer closes it with a note.' } : {}),
        ...(r.id === 'R-RED' ? { symptoms: redSyms.map((x) => SYM[x]?.label ?? x) } : {}),
        ...(r.id === 'R-RED' ? { cmoOnly: redSyms.every((x) => (SYM[x] as { commander?: boolean }).commander === false) } : {}),
      }))
    }
    const co2Hi = findings.some((x) => x.ruleId === 'R-CO2-HI')
    if (r.scope === 'environment' && day >= m.pre_days && evalCond(r.when, f) && !(r.id === 'R-CO2H' && findings.some((x) => x.ruleId === 'R-CO2' || x.ruleId === 'R-CO2-HI')) && !(r.id === 'R-CO2' && co2Hi)) {
      const start = r.id === 'R-CO2-HI' ? firstDay((t) => co2[t] >= 4.0) : r.id === 'R-CO2' ? firstDay((t) => co2[t] >= 3.0) : r.id === 'R-CO2H' ? day : firstDay((t) => rad[t] / radMed >= 3)
      const ind = r.id === 'R-SPE' ? 'rad' : 'co2'
      const v = env[ind]
      findings.push(mk(r, 'environment', start, r.id === 'R-CO2H' ? 'watch' : r.id === 'R-CO2-HI' ? 'urgent' : 'act', [{ ind, value: v, expected: r.id === 'R-SPE' ? radMed : 2.5, lo: 0, hi: r.id === 'R-SPE' ? radMed * 3 : 3.0, u3: NaN, z: NaN, direction: 'higher', percentile: NaN, daysOut: day - start + 1 }]))
    }
    if (r.scope === 'adaptation' && evalCond(r.when, f)) findings.push(mk(r, 'adaptation', Math.max(0, day - ph.since), applyRule(r, f).tier !== 'self' ? 'act' : 'watch', []))
  }
  // one finding per reading: when two fixed rules fire on the same indicator, the more urgent one stands
  for (let i = findings.length - 1; i >= 0; i--) {
    const a = findings[i]
    if (a.kind === 'vital' && findings.some((b) => b !== a && b.kind === 'vital' && rank[b.status] > rank[a.status] && (b.inds ?? []).some((x) => (a.inds ?? []).includes(x)))) findings.splice(i, 1)
  }
  if (alert && !learning) {
    // while an illness or fever finding is open, "do today's session" must not appear beside "no exercise"
    const restAdvised = findings.some((x) => NO_EXERCISE.has(x.ruleId))
    const seq = ruleSeq(restAdvised)
    const r = RULE[seq[seq.length - 1]] ?? RULE['R-GEN']
    // once this notice has looked like illness, it keeps exercise on hold and the medical officer involved
    // until the notice closes, even if the pattern now reads as something milder
    const wasIll = r.id !== 'R-ILL' && seq.includes('R-ILL')
    let patternDays = 1
    for (let k = seq.length - 2; k >= 0 && seq[k] === r.id; k--) patternDays++
    f.patternDays = patternDays
    const firstRule = patternDays < seq.length ? RULE[seq[0]] : null
    const noEx = restAdvised || r.id === 'R-ILL'
    const also = RULES.filter((q) => q.scope === 'personal' && q.id !== r.id && !['R-GEN', 'R-CARD'].includes(q.id) && !(noEx && q.id === 'R-EX') && evalCond(q.when, f)).map((q) => ({ title: q.title, action: q.action }))
    const t = applyRule(r, f)
    // Escalation beyond self-management needs the stricter detector tier (its own, smaller
    // false-alert budget) or a symptom the crew member reported themselves.
    const corroborated = alert.tier === 'alert' || symList.some((s) => ['sore_throat', 'cough', 'nausea', 'dizziness', 'vision'].includes(s)) || (sym.fatigue ?? 0) >= 2 || val.temp_oral.some((v) => v >= 38)
    const early = t.tier !== 'self' && !corroborated
    const status: Status = alert.tier === 'alert' || (t.tier !== 'self' && corroborated) ? 'act' : 'watch'
    const named = condIndicators(r.when)
    const evidence = [...changes.filter((c) => named.includes(c.ind)), ...changes.filter((c) => !named.includes(c.ind) && c.notable)].slice(0, 4)
    const cats = new Set<string>([...r.categories, ...evidence.map((c) => IND[c.ind]?.category ?? 'cardio')])
    findings.push(mk(r, 'personal', alert.start, status, evidence, {
      score: alert.score, threshold: model.thresholds.notice, categories: [...cats], detectorTier: alert.tier, days: patternDays, patternStart: day - patternDays + 1,
      firstNotice: firstRule ? { day: alert.start, title: firstRule.title } : undefined, also,
      factors: ['R-ILL'].includes(r.id) ? factors.filter((x) => x.id !== 'mood') : factors, urgency: (status === 'act' ? 'today' : 'routine') as Urgency,
      ...(wasIll ? { tier: (TIER_RANK[t.tier] < TIER_RANK.cmo ? 'cmo' : t.tier) as Tier, tierReason: 'Earlier in this notice the readings looked like illness. Keep the medical officer involved, and no exercise until they agree.', holdsExercise: true } : {}),
      ...(early && !wasIll ? { tier: 'self' as Tier, tierReason: 'Early signal. Keel will suggest involving the medical officer if it strengthens, lasts, or you report symptoms.', action: r.action.replace(/,? and tell the medical officer\.$/, '.').replace(/ Tell the medical officer\.$/, '') } : {}),
    }))
  }
  // one illness finding, not two: when the detector's own illness pattern is open it replaces the symptom-led one
  // (the merged finding keeps whichever urgency, status and audience is the more serious)
  const ill = findings.find((x) => x.ruleId === 'R-ILL')
  if (ill) for (let i = findings.length - 1; i >= 0; i--) if (findings[i].ruleId === 'R-SYM-ILL') {
    const sy = findings[i]
    if (rank[sy.status] > rank[ill.status]) Object.assign(ill, { status: sy.status, urgency: sy.urgency, action: sy.action, tier: TIER_RANK[sy.tier] > TIER_RANK[ill.tier] ? sy.tier : ill.tier, tierReason: sy.tierReason })
    // the merged finding dates from whichever began first, so every screen gives the same "since" day
    const began = Math.min(ill.patternStart ?? ill.start, sy.start)
    Object.assign(ill, { patternStart: began, days: day - began + 1 })
    findings.splice(i, 1)
  }
  findings.sort((a, b) => rank[b.status] - rank[a.status])
  const status: Status = findings.length ? findings[0].status : learning || staleDays >= 2 ? 'learning' : 'steady'

  // --- one status per area, used by every screen (body map, sharing preview, role views) ------
  const co2Today = lastValid(co2, day)
  const envStatus: Status = findings.some((x) => x.kind === 'environment') ? 'act' : co23 >= 2.5 || co2Today >= 2.5 ? 'watch' : 'steady'
  const sleepLast = lastValid(rawSeries(m, crewId, 'sleep_h', entries), day, 1)
  const areaStatus = (inds: string[]): Status => {
    let st: Status = 'learning'
    for (const id of inds) {
      const j = ids.indexOf(id)
      if (j < 0) continue
      const uu = u3[id]
      if (Number.isNaN(uu)) continue
      // without an open alert an area can be at most "worth a look"; "act" always comes from a finding
      const one: Status = uu >= 2 || uAt(day, j) >= 3 ? 'watch' : 'steady'
      if (rank[one] > rank[st]) st = one
    }
    // an area shows the worst open finding that rests on any of its indicators, fixed-threshold rules included
    for (const fd of findings) {
      if (fd.kind === 'environment') continue
      const ev = fd.inds ?? fd.changes.map((c) => c.ind)
      if (ev.some((e) => inds.includes(e)) && rank[fd.status] > rank[st]) st = fd.status
    }
    // a fixed floor beside the personal range: a night under five hours is worth a look whatever is usual for you
    if (inds.includes('sleep_h') && sleepLast < SLEEP_FLOOR_H && rank[st] < rank.watch) st = 'watch'
    return st
  }
  const allInds = Object.keys(IND).filter((i) => IND[i].category !== 'environment')
  const systems: Record<string, Status> = {}
  for (const sysId of [...new Set(allInds.map((i) => IND[i].system))]) systems[sysId] = areaStatus(allInds.filter((i) => IND[i].system === sysId))
  systems.environment = envStatus
  const categories: Record<string, Status> = {}
  for (const cat of [...new Set(allInds.map((i) => IND[i].category))]) categories[cat] = areaStatus(allInds.filter((i) => IND[i].category === cat))
  const symFinding = findings.find((x) => x.kind === 'symptom' || x.kind === 'adaptation' || x.ruleId === 'R-CO2H')
  // A single tick of a common symptom is not a flag (stuffiness is near-universal in weightlessness):
  // the area turns amber for a symptom on two of the last three days (tiredness: all three), or
  // two different ones today.
  const COMMON = ['congestion', 'fatigue']   // background complaints: these count only on three days running
  const symToday = symptomsOn(m, crewId, day, entries).filter((x) => x in SYM && !COMMON.includes(x))
  const symRepeat = symList.some((x) => sym[x] >= (COMMON.includes(x) ? 3 : 2) && x !== 'congestion')
  categories.symptoms = symFinding ? symFinding.status : symRepeat || symToday.length >= 2 ? 'watch' : 'steady'
  categories.environment = envStatus

  // --- 'now' and 'today' findings from the crew member's own entries, for the medical officer to close ---
  const openItems: OpenItem[] = []
  for (const e of mineE) {
    if (e.day > day) continue   // no time limit: an item leaves the list only when the medical officer closes it
    const vv = (id0: string, withVoid: boolean) => { const id = SPOT_KEY[id0] ?? id0; const log = (e.readings ?? []).filter((x) => x.ind === id && (withVoid || !x.void)).map((x) => x.v); return log.length ? log : (e.readings ?? []).some((x) => x.ind === id) ? [] : id in e.values ? [e.values[id]] : [] }
    const feats = (withVoid: boolean): RuleFeatures => ({
      u: {}, sym: Object.fromEntries(e.symptoms.map((x) => [x, 1])), env: {}, phaseDays: 0, hasPhase: false, alertDays: 0, patternDays: 0, run: () => [], rel: {},
      redFlag: [...e.symptoms, ...(e.redFlags ?? [])].some((x) => SYM[x]?.red_flag),
      val: { temp_oral: vv('temp_oral', withVoid), temp_oral_rise: [], glucose: vv('glucose', withVoid), sbp: vv('sbp', withVoid), dbp: vv('dbp', withVoid), spo2_manual: vv('spo2', withVoid), rhr_manual: vv('rhr', withVoid) },
    })
    const fAll = feats(true), fLive = feats(false)
    const fired = RULES.filter((r) => (r.scope === 'vital' || r.scope === 'symptom') && r.urgency !== 'routine' && evalCond(r.when, fAll))
    for (const r of fired) {
      // one item per reading: a more urgent rule on the same indicator stands for the lesser one
      const mine = condAll(r.when)
      if (mine.length && fired.some((q) => q !== r && q.urgency === 'now' && r.urgency !== 'now' && condAll(q.when).some((x) => mine.includes(x)))) continue
      const keys = condFixed(r.when).map((x) => SPOT_KEY[x] ?? x)
      const rts = (e.readings ?? []).filter((q) => keys.includes(q.ind)).map((q) => q.ts)
      // the latest live reading of each indicator: is it back on the safe side?
      const lastOnly: RuleFeatures = { ...fLive, val: Object.fromEntries(Object.entries(fLive.val).map(([k, vs]) => [k, vs.length ? [vs[vs.length - 1]] : vs])) }
      const glu = condFixed(r.when).includes('glucose')
      const liveTs = (e.readings ?? []).filter((q) => keys.includes(q.ind) && !q.void).map((q) => q.ts)
      const settledInTime = !glu || (liveTs.length > 1 && liveTs[liveTs.length - 1] - liveTs[0] >= 15 * 60 * 1000)
      const settled = r.scope === 'vital' && evalCond(r.when, fLive) && !RULES.some((q) => q.scope === 'vital' && condFixed(q.when).some((x) => condFixed(r.when).includes(x)) && evalCond(q.when, lastOnly)) && settledInTime
      openItems.push({ key: `open|${m.id}|${crewId}|${r.id}|${e.day}`, ruleId: r.id, title: r.title, day: e.day, urgency: r.urgency, category: r.categories[0], ts: rts.length ? Math.max(...rts) : e.ts,
        readings: (e.readings ?? []).filter((q) => keys.includes(q.ind)), symptoms: r.id === 'R-RED' ? [...new Set([...e.symptoms, ...(e.redFlags ?? [])])].filter((x) => SYM[x]?.red_flag).map((x) => SYM[x].label) : undefined, ...(evalCond(r.when, fLive) ? {} : { withdrawn: true }), ...(settled ? { settled: true } : {}) })
    }
  }
  openItems.sort((a, b) => b.day - a.day)
  // closed items leave the list; a reading after the closure note reopens them
  for (let i = openItems.length - 1; i >= 0; i--) if (isClosed(closed, openItems[i].key, openItems[i].ts)) openItems.splice(i, 1)

  const exerciseHold = findings.some((x) => NO_EXERCISE.has(x.ruleId) || (x as Finding & { holdsExercise?: boolean }).holdsExercise)
  return { status, findings, changes, learning, baselineDays, adapting, staleDays, u3, systems, categories, alert, features: f, co2Advisory: envStatus === 'watch' ? Math.max(co2Today || 0, co23 || 0) : null, openItems, exerciseHold }
}

/** Wording for a finding when the patient is the crew medical officer: the commander is the backup. */
function forCmoAsPatient(f: Finding): Finding {
  const sw = (t: string) => t
    .replace(/If you are the medical officer, tell the commander: they are your backup\./g, 'You are the medical officer, so the commander is your backup.')
    .replace(/[Tt]ell the (crew )?medical officer/g, (x) => (x[0] === 'T' ? 'Tell the commander (your medical backup)' : 'tell the commander (your medical backup)'))
    .replace(/see the medical officer/g, 'see the commander (your medical backup)')
    .replace(/show (it|both|the trend) to the medical officer/g, 'show $1 to the commander (your medical backup)')
    .replace(/talking to the medical officer/g, 'talking to the commander (your medical backup)')
    .replace(/with the medical officer/g, 'with the commander (your medical backup)')
  return { ...f, action: sw(f.action), steps: f.steps.map(sw), tierReason: sw(f.tierReason), who: f.who ?? 'The commander, as your medical backup' }
}

/** Plain-language sentence for one change. */
export function describeChange(c: Change): string {
  const def = IND[c.ind]
  const d = def.decimals
  const v = Number.isNaN(c.value) ? '–' : c.value.toFixed(d)
  if (Number.isNaN(c.u3)) return `${def.label} is ${v} ${def.unit}.`
  const dir = c.ind === 'sleep_mid' ? 'shifted from' : c.direction === 'higher' ? 'higher than' : 'lower than'
  return `${def.label}: ${v} ${def.unit}, ${dir} your usual ${c.expected.toFixed(d)}.${c.ind === 'temp' ? ' Wrist skin temperature, not a fever reading.' : ''}`
}

export function unusualness(c: Change): string {
  if (Number.isNaN(c.percentile) || !c.nHist) return 'Not enough history yet to say how unusual this is for you.'
  const days = c.daysOut > 1 ? ` Out of your range for ${c.daysOut} days.` : ''
  if ((c.nLess ?? 0) >= c.nHist) return `Your most unusual reading in ${c.nHist} days.${days}`
  return `More unusual than ${c.nLess} of your last ${c.nHist} days.${days}`
}

/** Which kind of evidence stands behind using this indicator. */
export function evidenceTag(ind: string): string {
  const e = (IND[ind] as unknown as { evidence?: string })?.evidence
  return e === 'real' ? 'Tested on real data' : e === 'reference' ? 'Fixed reference values' : 'Tested in simulation only'
}
